import subprocess
import ftplib
import os
from typing import List

def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser', ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test') -> List[str]:
    """
    Downloads all files from a specific directory on an FTP server using wget in a subprocess.
    """
    ftp = None
    try:
        ftp = ftplib.FTP(ftp_server)
    except Exception as e:
        raise Exception(f"Failed to connect to FTP server {ftp_server}: {str(e)}")

    try:
        ftp.login(user=ftp_user, passwd=ftp_password)
    except Exception as e:
        try:
            if ftp:
                ftp.quit()
        except Exception:
            pass
        raise Exception(f"Failed to log into FTP server {ftp_server} with user {ftp_user}: {str(e)}")

    try:
        ftp.cwd(ftp_dir)
    except Exception as e:
        try:
            if ftp:
                ftp.quit()
        except Exception:
            pass
        raise Exception(f"Failed to change to directory {ftp_dir} on server {ftp_server}: {str(e)}")

    filenames = []
    try:
        filenames = ftp.nlst()
    finally:
        try:
            if ftp:
                ftp.quit()
        except Exception:
            pass

    attempted_downloads = []
    local_dir = os.getcwd()

    for filename in filenames:
        base_name = os.path.basename(filename.rstrip("/"))
        if not base_name:
            continue

        # Construct the URL for wget. Ensure the path is properly formatted.
        ftp_url = f"ftp://{ftp_user}:{ftp_password}@{ftp_server}{ftp_dir.rstrip('/')}/{base_name}"
        command = [
            "wget",
            ftp_url,
            "-P", local_dir,
            "-nv" # -nv for non-verbose output to avoid clutter, optional
        ]

        attempted_downloads.append(base_name)
        # Run wget to download the file. We capture the intent by recording the base_name.
        # check=False because wget might fail for various reasons (e.g., file doesn't exist or permission),
        # but the task is to return what was *attempted*.
        subprocess.run(command, check=False)

    return attempted_downloads

